import sys

def main():
    import sys
    import math

    def query(c):
        print(f'? {c}')
        sys.stdout.flush()
        return input().strip()

    def reset():
        print('R')
        sys.stdout.flush()

    n, k = map(int, input().split())
    max_queries = (3 * n**2) // (2 * k)
    distinct_coffees = set()
    query_count = 0

    for i in range(1, n + 1):
        if query_count >= max_queries:
            break
        if query(i) == 'N':
            distinct_coffees.add(i)
        query_count += 1

    reset()

    for i in range(1, n + 1):
        if len(distinct_coffees) >= n:
            break
        if query(i) == 'N':
            distinct_count = 0
            for j in range(1, n + 1):
                if query(j) == 'Y':
                    distinct_count += 1
            if distinct_count == len(distinct_coffees):
                distinct_coffees.add(i)
        query_count += 1

    print(f'! {len(distinct_coffees)}')

main()
